  for var i := 0 to sorted.Length - 2 do
    if abs(sorted[i] - sorted[i + 1]) <= threshold then
    begin
      Result := True;
      exit;
    end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<string>;
  var current := new StringBuilder;
  var groups := new List<string>;
  var ignoreSpace := False;

  for var i := 1 to parenString.Length do
  begin
    var ch := parenString[i];

    if ch = ' ' then
    begin
      if ignoreSpace then
        continue;

      ignoreSpace := True;
      current.Append(ch);
    end
    else if ch = '(' then
    begin
      if ignoreSpace then
        current.Append(ch);

      stack.Push(current.ToString);
      current := new StringBuilder;
    end
    else if ch = ')' then
    begin
      current.Append(ch);

      if stack.Count > 0 then
      begin
        var group := stack.Pop;
        current.Append(group);
        groups.Add(current.ToString);
        current := new StringBuilder;
      end;
    end;
  end;

  Result := groups.ToArray;
end;


