function ParseNestedParens(parenString: string): array of integer;
begin
  var stack := new Stack<integer>;
  var maxDepth := 0;
  var currentDepth := 0;
  var start := 1;
  var parenList := new List<integer>;

  for var i := 1 to parenString.Length do
  begin
    var ch := parenString[i];
    if ch = '(' then
    begin
      currentDepth += 1;
      if currentDepth > maxDepth then
        maxDepth := currentDepth;
      stack.Push(i);
    end
    else if ch = ')' then
    begin
      currentDepth -= 1;
      var &end := i - 1;
      var &start := stack.Pop;
      parenList.Add(maxDepth);
    end;
  end;

  Result := parenList.ToArray;
end;

