function MakePalindrome(str: string): string;
begin
  var n := str.Length;
  var L := new integer[n, n];
  var maxLen := 1;
  var start := 0;

  for var i := 0 to n - 1 do
  begin
    L[i, i] := 1;
    if i < n - 1 then
      if str[i + 1] = str[i] then
        L[i, i + 1] := 2;
  end;

  for var len := 3 to n do
  begin
    for var i := 0 to n - len do
    begin
      var j := i + len - 1;
      if str[i + 1] = str[j + 1] then
        L[i, j] := L[i + 1, j - 1] + 2;
      if L[i, j] > maxLen then
      begin
        maxLen := L[i, j];
        start := i;
      end;
    end;
  end;

  var suffix := str.Substring(start, n - start);
  var prefix := str.Substring(0, start);
  Result := str + new string(suffix.Reverse.ToArray);
end;


