function ParseMusic(musicString: string): array of integer;
begin
  var beats := new List<integer>;
  var currentBeat := 0;
  var currentNote := '';

  for var i := 1 to musicString.Length do
  begin
    var c := musicString[i];

    if c = 'o' then
    begin
      if currentNote = 'o' then
        currentBeat += 4
      else
        currentBeat += 2;
    end
    else if c = '.' then
    begin
      if currentNote = '.' then
        currentBeat += 1
      else
        currentBeat += 1 div 2;
    end
    else if c = '|' then
    begin
      if currentNote = 'o' then
        currentBeat += 2
      else if currentNote = '.' then
        currentBeat += 1
      else
        currentBeat += 1 div 2;
    end;

    currentNote := c;
    beats.Add(currentBeat);
  end;

  Result := beats.ToArray;
end;


