  var decreasing := True;

  for var i := 0 to l.Length - 2 do
  begin
    if l[i] < l[i + 1] then
      decreasing := False
    else if l[i] > l[i + 1] then
      increasing := False;
  end;

  Result := increasing or decreasing;
end;


function Common(l1, l2: array of integer): array of integer;
