  while (i < l1.Length) and (j < l2.Length) do
  begin
    if l1[i] = l2[j] then
    begin
      if (common.Count = 0) or (common.Last <> l1[i]) then
        common.Add(l1[i]);
      i += 1;
      j += 1;
    end
    else if l1[i] < l2[j] then
      i += 1
    else
      j += 1;
  end;
  Result := common.ToArray;
end;


