function CorrectBracketing(brackets: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in brackets do
  begin
    if (ch = '(') or (ch = '{') or (ch = '[') then
      stack.Push(ch)
    else if (ch = ')') or (ch = '}') or (ch = ']') then
    begin
      if (stack.Count = 0) or (stack.Peek <> (if ch = ')' then '(' else if ch = '}' then '{' else '[')) then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;
  Result := stack.Count = 0;
end;


