function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var N := grid.Length;
  var dp := new integer[N, N, k + 1];
  for var i := 0 to N - 1 do
    for var j := 0 to N - 1 do
      for var z := 0 to k do
        dp[i, j, z] := integer.MaxValue;
  dp[0, 0, 0] := grid[0, 0];
  var dirs := |(0, 1), (1, 0), (0, -1), (-1, 0)|;
  var heap := new SortedSet<(integer, integer, integer)>;
  heap.Add((grid[0, 0], 0, 0));
  while heap.Count > 0 do
  begin
    var (cur, x, y) := heap.Min;
    heap.Remove(heap.Min);
    foreach var (dx, dy) in dirs do
    begin
      var nx := x + dx;
      var ny := y + dy;
      if (nx >= 0) and (nx < N) and (ny >= 0) and (ny < N) then
      begin
        var newVal := cur + grid[nx, ny];
        if newVal < dp[nx, ny, k] then
        begin
          for var i := 0 to k - 1 do
            dp[nx, ny, i] := dp[nx, ny, i + 1];
          dp[nx, ny, k] := newVal;
          heap.Add((newVal, nx, ny));
        end;
      end;
    end;
  end;
  var path := new List<integer>;
  for var i := 0 to k - 1 do
    path.Add(dp[N - 1, N - 1, i]);
  path.Sort;
  Result := path.ToArray;
end;

begin
end.




