      stack.Push(ch)
    else if (ch = ']') or (ch = '}') or (ch = ')') then
    begin
      if (stack.Count = 0) or (stack.Peek <> (
        case ch of
          ']': '[';
          '}': '{';
          ')': '(';
        end)) then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;
  Result := stack.Count = 0;
end;


