  roman.Add(400, 'cd');
  roman.Add(100, 'c');
  roman.Add(90, 'xc');
  roman.Add(50, 'l');
  roman.Add(40, 'xl');
  roman.Add(10, 'x');
  roman.Add(9, 'ix');
  roman.Add(5, 'v');
  roman.Add(4, 'iv');
  roman.Add(1, 'i');

  var res := '';
  var num := number;

  foreach var kv in roman do
  begin
    while num >= kv.Key do
    begin
      res += kv.Value;
      num -= kv.Key;
    end;
  end;

  Result := res;
end;

