function RightAngleTriangle(a, b, c: integer): boolean;
begin
  var sides := new integer[3];
  sides[0] := a;
  sides[1] := b;
  sides[2] := c;
  &Array.Sort(sides);
  Result := (sides[2] * 2 = a + b) or (sides[2] * 2 = b + c) or (sides[2] * 2 = c + a);
end;


function FindMax(words: array of string): string;
begin
  var maxUnique := 0;
  var maxWord := '';

  foreach var word in words do
  begin
    var uniqueChars := new HashSet<char>(word.ToCharArray);
    var uniqueCount := uniqueChars.Count;

    if uniqueCount > maxUnique then
    begin
      maxUnique := uniqueCount;
      maxWord := word;
    end;
  end;

  Result := maxWord;
end;

begin
end.




function Eat(number, need, remaining: integer): (integer, integer);
begin
  var eaten := number;
  var left := remaining;

  if left >= need then
  begin
    eaten := eaten + need;
    left := left - need;
  end
  else
  begin
    eaten := eaten + left;
    left := 0;
  end;

  Result := (eaten, left);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 1 to operand.Length - 1 do
  begin
    case op[i-1] of
      '+': res := res + operand[i];
      '-': res := res - operand[i];
      '*': res := res * operand[i];
      '//': res := res div operand[i];
      '**': res := res * operand[i];
    end;
  end;
  Result := res;
end;

begin
end.




function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  foreach var ch in s do
  begin
    if char.IsLetter(ch) then
    begin
      if char.IsLower(ch) then
        sb.Append(char.ToUpper(ch))
      else
        sb.Append(char.ToLower(ch));
    end
    else
      sb.Append(ch);
  end;
  Result := sb.ToString;
end;

begin
end.




function StringToMd5(text: string): string;
begin
  if text = '' then
  begin
    Result := nil;
    exit;
  end;

  var md5 := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var bytes := System.Text.Encoding.UTF8.GetBytes(text);
  var hash := md5.ComputeHash(bytes);

  var sb := new System.Text.StringBuilder;
  foreach var b in hash do
    sb.Append(b.ToString('x2'));

  Result := sb.ToString;
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var res := new List<integer>;
  for var i := a to b do
    if (i mod 2 = 0) and (i mod 5 <> 0) then
      res.Add(i);
  Result := res.ToArray;
end;

